try{using(var tx=new Transaction(document,"Match roof surface pitches to source drawings")){tx.Start();foreach(var r in new FilteredElementCollector(document).OfClass(typeof(FootPrintRoof)).Cast<FootPrintRoof>()){var mark=r.get_Parameter(BuiltInParameter.ALL_MODEL_MARK).AsString();if(mark==null||!mark.StartsWith("ROOF-"))continue;double angle=mark=="ROOF-MAIN"?25:5;foreach(ModelCurveArray loop in r.GetProfiles())foreach(ModelCurve c in loop)if(r.get_DefinesSlope(c))r.set_SlopeAngle(c,Math.Tan(angle*Math.PI/180));}tx.Commit();}document.Save();return new{warnings=document.GetWarnings().Select(w=>w.GetDescriptionText()).ToArray()};}catch(Exception e){return new{failure=e.ToString()};}
